SELECT order_id, CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END AS unit_price_bucket, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(AVG(unit_price), 2) AS avg_unit_price, AVG(quantity) AS avg_quantity FROM order_items WHERE product_id IN (16, 22, 40) GROUP BY order_id, CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END;
